import { useCallback, useEffect, useState } from "react";
import { InlineError } from "./primitives/InlineError";
import { Overlay } from "./primitives/Overlay";
import { Panel } from "./primitives/Panel";
import styles from "./ThirdPartyLicencesDialog.module.css";

type LoadState = { kind: "loading" } | { kind: "loaded"; text: string } | { kind: "error"; message: string };

/**
 * Shows THIRD_PARTY_NOTICES.md (generated by scripts/generate-third-party-notices.py): the
 * licences of the code Browsitory ships. The text is a separate static file, loaded on demand
 * by `load`, so it doesn't weigh on the app's script bundle.
 */
export function ThirdPartyLicencesDialog({ load, onClose }: { load: () => Promise<string>; onClose: () => void }) {
  const [state, setState] = useState<LoadState>({ kind: "loading" });
  const [attempt, setAttempt] = useState(0);

  useEffect(() => {
    let cancelled = false;
    load().then(
      (text) => {
        if (!cancelled) setState({ kind: "loaded", text });
      },
      (error: unknown) => {
        if (!cancelled) setState({ kind: "error", message: error instanceof Error ? error.message : String(error) });
      },
    );
    return () => {
      cancelled = true;
    };
  }, [load, attempt]);

  const retry = useCallback(() => {
    setState({ kind: "loading" });
    setAttempt((n) => n + 1);
  }, []);

  return (
    <Overlay onClose={onClose} ariaLabel="Third-party licences" closeOnBackdropClick>
      <Panel
        title="Third-party licences"
        ariaLabel="Third-party licences"
        // In the footer, Close stays in view however long the dialog gets.
        footer={
          <button type="button" onClick={onClose}>
            Close
          </button>
        }
      >
        <p className={styles.intro}>
          Browsitory includes open source software. These are its licences and copyright notices.
        </p>
        {state.kind === "loading" && (
          <p role="status" className={styles.status}>
            Loading licences…
          </p>
        )}
        {state.kind === "error" && (
          <InlineError
            message={state.message}
            hint="The licences could not be loaded. The same text is in the THIRD_PARTY_NOTICES.md file that comes with Browsitory."
            onRetry={retry}
            onDismiss={onClose}
          />
        )}
        {state.kind === "loaded" && (
          // A focusable region so keyboard users can scroll the long text.
          <pre className={styles.text} role="region" aria-label="Licence texts" tabIndex={0}>
            {state.text}
          </pre>
        )}
      </Panel>
    </Overlay>
  );
}
